      CommsLine(id: 'lowLives.h2', speaker: 'anvil', duration: 3.191, text: 'One ship left. Slow down, pick your shots.', mouth: '000<<<<<<<<444==00000===<<<<<<<2222222==<<<===00', open: '004888878767753211000466899999742127567787455321', vis: '--ooooeeoo----ee-----eeeooo-----------ee---ee---', emotion: 'warm'),
      CommsLine(id: 'lowLives.h3', speaker: 'wisp', duration: 3.267, text: 'Final reserve ship. Stay calm. You can do this.', mouth: '000<<<<<<<<======00=======33332200000<<<<<<====000', open: '02788888899776532112337864565532116868899885332110', vis: 'ee---------eeeeee--eee---------------oo----eeee---', emotion: 'warm'),
