  'flawlessSector': CommsTriggerSpec(
    name: 'flawlessSector',
    priority: 6,
    cooldown: 10.0,
    ttl: 4.0,
    mood: CommsMood.happy,
    lines: [
      CommsLine(id: 'flawlessSector.h0', speaker: 'admiral', duration: 3.43, text: 'Not a single ship lost in this sector. Textbook, all of you.', mouth: '55555========445555555<<=====44======442222<<<<<<<22', open: '0578743266876774478757886375366422764774216899999642', vis: 'oo---eeeee-----oo----oooee-----ee--ee-----------oo--', emotion: 'triumphant'),
      CommsLine(id: 'flawlessSector.h1', speaker: 'kestrel', duration: 3.15, text: 'Every wing accounted for. That\'s how it\'s done.', mouth: '3344<<<<<<<==444444<<<==0000<<===<<<<<<<<<<<<222', open: '056788899985477874688743212688536897532788986321', vis: '-----oooo--ee-----oo--eeeee---ee----------------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessSector.h2', speaker: 'sunny', duration: 2.522, text: 'Zero losses! That was out of this world.', mouth: '2222<<<<<<<<============44433355<<<<22', open: '03458899887754442278785577756447888532', vis: '------------ee--eeeeeeee------oo------', signature: true, emotion: 'teasing'),
      CommsLine(id: 'flawlessSector.h3', speaker: 'march', duration: 4.039, text: 'Bastion reporting. Every ground team is still standing. Thank you!', mouth: '33====333322244442222<<<<<<<<3355===<<===<<<<<<2222<<<<<<5555', open: '0665325666426776632168886688866774278853788888632178857887432', vis: '--eeee-------------------------ooeee--eeeee--------------oo--', emotion: 'triumphant'),
