  'flawlessVictory': CommsTriggerSpec(
    name: 'flawlessVictory',
    priority: 9,
    cooldown: 30.0,
    ttl: 6.0,
    mood: CommsMood.happy,
    chain: 2,
    lines: [
      CommsLine(id: 'flawlessVictory.h0', speaker: 'admiral', duration: 5.96, text: 'All hands, all ships, all squads. Every one of you is coming home. Fleet intact!', mouth: '33<<<33333222<<==33======222444=====44444333===4444<<<555000<<<<=======<<===00000004433322', open: '068976666543688756642178743677532168776876664247777888642115898542168668963211004787666742', vis: '---------------ee--ee----------eeee---------eee------oooo-------eeeeooeeeeee--------------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessVictory.h1', speaker: 'lindqvist', duration: 4.426, text: 'Beacon confirms. Full roster, no losses. I\'ve never seen it done.', mouth: '=========3333==000044<<<==3330055<<<<<33333000000<<<<<444444<<<<222', open: '0453565535665321100678975565321568989756542111576889896678778876421', vis: 'eeeeeeeee----ee---------ee-----ooo--------ee----ooo----------------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessVictory.h2', speaker: 'rook', duration: 3.326, text: 'Perfect run! I\'m over the moon! All the moons!', mouth: '22222============444<<44<<<<<<<2222<<<<<<<<<<<2200', open: '03537645777653215775897788888864237998888888753211', vis: '-----eeeeeeeee------oo----------------------------', signature: true, emotion: 'teasing'),
      CommsLine(id: 'flawlessVictory.h3', speaker: 'sunny', duration: 2.588, text: 'Flawless! Somebody get this pilot a constellation!', mouth: '55<<<<<<===000<<<<<===<<<<<4444<<======', open: '058999986321158888864788745776788656432', vis: 'oo------eee--------ee------------eeee--', signature: true, emotion: 'teasing'),
      CommsLine(id: 'flawlessVictory.h4', speaker: 'pip', duration: 2.72, text: 'Everybody made it? Everybody? Best day ever!', mouth: '223334444<<<<<<<<<<<<==00000000<<<<<<<<<<', open: '04565777788856898988632116875378878989853', vis: '--------eeeoo--------ee------------------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessVictory.h5', speaker: 'kessler', duration: 3.289, text: 'Ground\'s all present! Drinks are on Bulwark tonight!', mouth: '000<<<<<<<<<555<<<<==00003333<<<<<<<<<<<<<<<<<<000', open: '00589885788853589874211126646898536888853678743211', vis: '-----------ooo-----ee-------------oooo--------ee--', emotion: 'triumphant'),
