  'flawlessRun': CommsTriggerSpec(
    name: 'flawlessRun',
    priority: 10,
    cooldown: 60.0,
    ttl: 8.0,
    mood: CommsMood.happy,
    chain: 3,
    lines: [
      CommsLine(id: 'flawlessRun.h0', speaker: 'admiral', duration: 6.202, text: 'Five tours. Not one ship, not one squad lost. The whole fleet salutes you, pilot.', mouth: '44<<<<<222222===0000000555<<======000005555<<===<<<<<<<<===0002222<<<444========44444<<<<<==00', open: '0689986326787532110068643788778743215875447985358986679964321142178856753466785377467888754211', vis: '-------------eee-------oo---eeee-------ooo---eee--------eeee-----oooo---eeee--------------ee--', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h1', speaker: 'nomad', duration: 3.352, text: 'Thirty years flying, and this is the run I\'ll tell stories about.', mouth: '33<<<<<<<<<<<<<<<22000<<<<<<<<<<<<<<==<<<<<<4444000', open: '068778999867988653211689887889888578758888887753211', vis: '------------------------------------eeoo-------ee--', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h2', speaker: 'kestrel', duration: 4.273, text: 'Every wing, every crew, every squad. Fleet intact. Legendary.', mouth: '22244444555000<<<33<<5555444===<<<<=====335555======<<<<<<<<<<222', open: '04677777642116888568974337786568887421586677787421368988898997421', vis: '--------oooo--oo---ooooo----eee----eee----oooeeeee---------------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h3', speaker: 'sparrow', duration: 3.168, text: 'Not a scratch on the whole fleet! You\'re unbelievable!', mouth: '55533==0033===44455=======00000<<<<<44<<<<<<<222', open: '046654211564356656642355332113689988778989997421', vis: 'oo---ee----ee----ooeeeeeeee---------------------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h4', speaker: 'mensah', duration: 3.305, text: 'Granite to air wing. Every trooper down here is cheering for you.', mouth: '555<<4444<<<<<<555544433344<<<<<<<<===<<<<<<<<3333', open: '03788677789888874327786586779888885347886478876432', vis: 'oooee---eeeeeeeooo-----------------ee-----oo------', emotion: 'triumphant'),
      CommsLine(id: 'flawlessRun.h5', speaker: 'voss', duration: 3.416, text: 'Lantern here. All lights on, all teams home. Thank you, pilot!', mouth: '55<<555444======<<<<<<<<<22224444444422223333<<<<222', open: '0488777778764217889857887437876657776325756468897432', vis: 'oooooo---eeeee--------------------------------------', emotion: 'triumphant'),
    ],
  ),
