    ttl: 4.0,
    mood: CommsMood.worried,
    lines: [
      CommsLine(id: 'defeat.h0', speaker: 'admiral', duration: 5.154, text: 'All ships totalled, but every pilot is safe. Regroup at base. We go again.', mouth: '44<<<444===<<444440033<<<<<<<<<<<<===33==000000000<<<<44444===0000000<<<<<<<22', open: '068987776568777653216589888547887665466421110027878986766764432110587888887642', vis: '--------eee-----------------------eee--eee----oo-----------eee----ooo---------', emotion: 'exhausted'),
      CommsLine(id: 'defeat.h1', speaker: 'admiral', duration: 4.114, text: 'That\'s the last reserve. Bring it home, pilot. We\'ll launch again.', mouth: '33<<<===<<<<======<<<<<00000000<<<<<<<<<<<<<=====<<<<<<<<<<<<<', open: '04887537899865576788642111000068989987788888643268999886888743', vis: '-----eeee---eeeee-----ee------------oo--oo--ee----------------', emotion: 'exhausted'),
