      CommsLine(id: 'groundForceSighted.h1', speaker: 'wisp', duration: 2.291, text: 'Demon ground troops below. Marking them now.', mouth: '33333333333333<<<<====<<<<<44444222', open: '05787578767656899853278967877776421', vis: '------------------eee--------------', emotion: 'urgent'),
      CommsLine(id: 'groundForceSighted.h2', speaker: 'anvil', duration: 2.358, text: 'Movement on the ground. Brood infantry.', mouth: '22222<<<<<<<<<<<<<0000<<<<<<<=======', open: '037878887678998753211489999787676421', vis: '--ooo---------------------eeeeeeee--', emotion: 'urgent'),
      CommsLine(id: 'groundForceSighted.h3', speaker: 'kessler', duration: 2.748, text: 'Bulwark here. Brood walkers moving on our line!', mouth: '55555<<=======000000<<<<<4444<<<<<<<<<====', open: '058778854787432126768988777678999899986321', vis: 'ooooo--eeee--ee----------------------eee--', emotion: 'urgent'),
