      CommsLine(id: 'allyUnderAttack.h1', speaker: 'kessler', duration: 2.671, text: 'Please shoot these enemies! They\'re all over us!', mouth: '5533=======333<<44====<<<<<<<33<<<<<===00', open: '04654434664557887642148858998558889754211', vis: 'oo--eeeeee--------eee---------------eee--', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h2', speaker: 'voss', duration: 2.469, text: 'Pick up some homing missiles! We need them off our backs!', mouth: '333<<<<<<<<<<<555554444<<<<<<<<<====00', open: '05688789889888743267787898898998543211', vis: '-----------ooooooo------------eeeeee--', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h3', speaker: 'march', duration: 4.75, text: 'Bastion to air wing, my teams are taking fire. Requesting support!', mouth: '===44====<<====333<<<<<<<<<<<<<<<<=====333==5555<<<<<2222222244333<<<<22', open: '046774324887565657888887532378876766678557767547889853276379577666898642', vis: 'ee---eee---eeee-----oo------------eee-----eeooo--ee---------------------', emotion: 'panicked'),
      CommsLine(id: 'allyUnderAttack.h4', speaker: 'mensah', duration: 2.609, text: 'Granite\'s surrounded! Anything you\'ve got, send it down!', mouth: '555<<<<33<<<<<222===44555<<==4444<<<<<<<', open: '0267864557987632466577647985377858988532', vis: 'oo---------------ee---ooo--ee-----ee----', emotion: 'panicked'),
