      CommsLine(id: 'allyUnderAttack.h6', speaker: 'march', duration: 2.913, text: 'Bastion is under heavy fire! We need you now!', mouth: '==44==5553333==444222<<<<<<<<<<<<<44<<<<<222', open: '05776345555553377742789874325887887788876421', vis: 'ee--eeooo----ee-------ee---ooooo------ee----', emotion: 'panicked'),
