      CommsLine(id: 'allySaved.h7', speaker: 'kessler', duration: 2.832, text: 'Whew. That was close. Thanks, friend!', mouth: '000000<<<22000000000222<<<======<<===<<<<22', open: '0000058853211017878644688755321588657888742', vis: '-----------------ooo------eee--eeeee-------', emotion: 'exhausted'),
