      CommsLine(id: 'broodTaunt.h1', speaker: 'rook', duration: 3.317, text: 'Yeah, yeah. Big talk from a flying gargoyle.', mouth: '000<<<<<333<<<<==0004444<<<<333===<<<44<<<55552200', open: '01579987667898742113774589745553268887689877764321', vis: '---------------eee-------------eee--------oo------', emotion: 'teasing'),
      CommsLine(id: 'broodTaunt.h2', speaker: 'sparrow', duration: 1.874, text: 'Was that a threat? Cute.', mouth: '55555<<44<<====0000000055====', open: '04637897788764211000378746321', vis: 'oooo-------eeee-------oooee--', emotion: 'teasing'),
      CommsLine(id: 'broodTaunt.h3', speaker: 'anvil', duration: 2.216, text: 'Keep growling. It won\'t save you.', mouth: '0000===<<<<<==000000<<<<<<<4442200', open: '0258657899864211105689788997664211', vis: 'eeeeeee-----eee----oooeee---------', emotion: 'calm'),
      CommsLine(id: 'broodTaunt.h4', speaker: 'kestrel', duration: 3.358, text: 'Kestrel to brood: we heard you. Come and try it.', mouth: '000===<<<=====<<<<<4444<<<444333000000<<<<44<<<<222', open: '006655899566368998777468887776532110168886678876421', vis: '---eee---eeee--oooo--------------------------------', emotion: 'stern'),
      CommsLine(id: 'broodTaunt.h5', speaker: 'sunny', duration: 2.63, text: 'Somebody needs a breath mint. And a new career.', mouth: '000<<<<<<<5555======000000<<<<<44<<<<222', open: '0068888888557874565321100589995678886421', vis: '----------oo--eeeeeee------------ee-----', emotion: 'teasing'),
      CommsLine(id: 'broodTaunt.h6', speaker: 'pip', duration: 2.756, text: 'Was that at me? Okay. Okay! I\'m not scared!', mouth: '555444333555555<<<<2255<<<<222<<<==<<<<222', open: '034777556632576899642658997436898778897432', vis: 'ooo------oooooo--ee--oo----------eeee-----', emotion: 'excited'),
      CommsLine(id: 'broodTaunt.h7', speaker: 'nomad', duration: 2.505, text: 'I\'ve heard scarier thunderstorms, friend.', mouth: '33<<<<<<<====<<<<<<<<<<==5555====33333', open: '05886899876478888757898756766536666532', vis: '---------eee-----------eeooooee-------', emotion: 'calm'),
      CommsLine(id: 'broodTaunt.h8', speaker: 'wisp', duration: 2.74, text: 'Translation: they\'re nervous. Good.', mouth: '=====<<<<55522000000<<<<<<===0000000000222', open: '037868988765321100478888764421100003786421', vis: 'ee-----eeooo--------------eee-------------', emotion: 'calm'),
      CommsLine(id: 'broodTaunt.h9', speaker: 'lindqvist', duration: 2.668, text: 'Noted. Logged. Ignored.', mouth: '55<<<<33==000000000<<<22000000000<<55==00', open: '05898655321100000378853321100054688765321', vis: 'oo------ee------------------------oooee--', emotion: 'calm'),
      CommsLine(id: 'broodTaunt.h10', speaker: 'march', duration: 2.43, text: 'Bastion hears you, brood. We\'re not moving.', mouth: '3333=====<<44444455====<<<<<<<<<<3333', open: '0578767778877757777642689998998876532', vis: '----eeee---------ooeeeeee------------', emotion: 'stern'),
      CommsLine(id: 'broodTaunt.h11', speaker: 'kessler', duration: 3.12, text: 'Bulwark to brood: come down here and say that.', mouth: '00000033333==00000<<<====<<<222<<<<<<4444433222', open: '00114765787432111789977678874368899887756765321', vis: '-----------eee---ooooeee-----------------------', emotion: 'teasing'),
    ],
  ),
  'playerRespawn': CommsTriggerSpec(
    name: 'playerRespawn',
    priority: 5,
    cooldown: 6.0,
    ttl: 4.0,
    delay: 0.6,
    lines: [
      CommsLine(id: 'playerRespawn.h0', speaker: 'admiral', duration: 3.8, text: 'Spare ship on deck four, launch! You\'re clear, pilot.', mouth: '00===<<==<<<<<<<<<==554442222<<<<=====00555555<<334444====', open: '0232789778868988853267766321589966653211378537885677776321', vis: 'eeee---eeee--oo---eeoo------oo---eeeee--oo------------ee--', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h1', speaker: 'lindqvist', duration: 3.381, text: 'Reserve fighter is hot. Welcome back to the fight.', mouth: '333<<<33<<4433322255===000000000<<<<<<<<<<224442222', open: '056899568866565324743421100000068978898667447754421', vis: '------------------ooeee------------oo--------------', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h2', speaker: 'kestrel', duration: 3.66, text: 'New ship, same pilot. Form up on me.', mouth: '000000<<<=====0000<<<<44442200000000<<<<<<<<<<443322000', open: '0000278997664211258986776532110000068999878887776532110', vis: '-----ooooeeeee------------------------------oo---------', emotion: 'calm'),
      CommsLine(id: 'playerRespawn.h3', speaker: 'nomad', duration: 3.773, text: 'Fresh paint, fresh engines. Take it easy for a second.', mouth: '00000000<<<55500000<<<<<<<<555==000044<<<<<<4444444552200', open: '001787478985421101688789988766532112778889886776785654211', vis: '---------oooo-------eeeoooooooeee------------------oo----', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h4', speaker: 'anvil', duration: 2.235, text: 'Back in the air. Shake it off.', mouth: '5555==333<<<<2200==<<<<<5550000000', open: '0368766678975321126898997532110000', vis: 'oo--ee-----------eee---oooee------', emotion: 'calm'),
      CommsLine(id: 'playerRespawn.h5', speaker: 'sparrow', duration: 2.305, text: 'There you are! Don\'t scare me like that.', mouth: '00000<<<<444440000000<<<<<<<333==00', open: '00037888777542117874689988646643211', vis: '-------oo----ee-------oo-------ee--', emotion: 'excited'),
      CommsLine(id: 'playerRespawn.h6', speaker: 'rook', duration: 2.231, text: 'New ship smell! Try not to scratch this one.', mouth: '33<<<<<===<<<<<<<<<444<<=====22000', open: '0589878667888746888776886764442111', vis: '--ooeeeeee-------------eeeee------', emotion: 'teasing'),
      CommsLine(id: 'playerRespawn.h7', speaker: 'wisp', duration: 3.514, text: 'Reserve ship launched. Shields at full. Blink and go.', mouth: '333<<<<<<<33<<<<====00000000<<<44444<<555555334444444', open: '05689988885688745432110000168997764688642478667776532', vis: '------ee----oo--eeee-------ee--------oooo------------', emotion: 'calm'),
      CommsLine(id: 'playerRespawn.h8', speaker: 'sunny', duration: 2.428, text: 'Rise and shine! Look who\'s back.', mouth: '000<<<<5544444433220000000000<<===000', open: '0058988766777776542110068578689742111', vis: '------ooo------------------oo--eeee--', emotion: 'excited'),
      CommsLine(id: 'playerRespawn.h9', speaker: 'pip', duration: 2.159, text: 'You\'re back! I knew you\'d be back!', mouth: '33<<55<<<===00000<<<<<<<<<<<<==00', open: '058874888532117878888888978874321', vis: '----oo---eee----oo-----------ee--', emotion: 'excited'),
      CommsLine(id: 'playerRespawn.h10', speaker: 'march', duration: 2.564, text: 'Bastion sees your new ship. We\'re still with you.', mouth: '33<<=======<<444<<====222<<<<<<<4433300', open: '058875666578877788768642688689987754321', vis: '----eeeeee-----oooee------eeeeee-------', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h11', speaker: 'kessler', duration: 1.975, text: 'Ground\'s glad to see you up there again!', mouth: '22244444<<<===<<<<<<<<<<<<<<22', open: '026776478865568898578978888642', vis: '-----------ee------eee----oo--', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h12', speaker: 'voss', duration: 2.636, text: 'Lantern lights for the new ship. Go get them.', mouth: '55<<<<<<<<==44<<<<<<<5500000000000002200', open: '0589888999757788887885321100687978764211', vis: 'ooee------ee-----eeoooo-----------------', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h13', speaker: 'mensah', duration: 2.338, text: 'Granite here. Solid launch, flyer.', mouth: '33<<<===2200000<<<<<<<<==0000<<<<222', open: '048885444321116889788754211068875321', vis: '-----ee---------oooo---ee-----------', emotion: 'calm'),
      CommsLine(id: 'playerRespawn.h14', speaker: 'admiral', duration: 3.802, text: 'Recovery has your pod. Your reserve is ready. Fly.', mouth: '33333444444<<<<<<4442200000<<<<<<<<<<44<<<<==00000<<<<<222', open: '0675877877688786677642110058897899868768886432110588875321', vis: '--------------oo------------ooo------------eee------------', emotion: 'warm'),
      CommsLine(id: 'playerRespawn.h15', speaker: 'nomad', duration: 3.69, text: 'Every great pilot loses a ship. Great ones get back up.', mouth: '33<<<<<<<<33<<<55<<<<<<====2200000000<<<<<<=======333300', open: '06887887985589977898888778642110000068888986686774565321', vis: '---------------oooo----ee-------------oooooeeeeeee------', emotion: 'warm'),
    ],
  ),
  'groundMissileLaunch': CommsTriggerSpec(
    name: 'groundMissileLaunch',
    priority: 6,
    cooldown: 12.0,
    ttl: 1.5,
    chance: 0.5,
    group: 'ground',
    lines: [
      CommsLine(id: 'groundMissileLaunch.h0', speaker: 'kessler', duration: 1.992, text: 'Missile up! It\'s going for you!', mouth: '5544444<<<2222222<<<<334445555', open: '037757789742532178874666776421', vis: 'oo------------ee----------oo--', emotion: 'urgent'),
      CommsLine(id: 'groundMissileLaunch.h1', speaker: 'voss', duration: 2.041, text: 'Launch from the ground! Break off!', mouth: '55<<<334455<<<33220000<<<<<==00', open: '0488755676788765321137889974211', vis: 'oo-------ooee--------------ee--', emotion: 'urgent'),
      CommsLine(id: 'groundMissileLaunch.h2', speaker: 'anvil', duration: 1.986, text: 'Missile from below. Move.', mouth: '224443322333<<<<55555<<<<<5555', open: '036776534657889875324899986421', vis: '-----------oo---ooee-----ooo--', emotion: 'urgent'),
      CommsLine(id: 'groundMissileLaunch.h3', speaker: 'wisp', duration: 2.487, text: 'Ground launch detected. Sidestep it.', mouth: '555<<<<<55333====4444000000<<===333222', open: '03788888765544744775321101588547556421', vis: 'ooo----ooo---eeee------------eee------', emotion: 'urgent'),
      CommsLine(id: 'groundMissileLaunch.h4', speaker: 'mensah', duration: 1.934, text: 'Granite sees a missile! Watch out!', mouth: '000=====223333<<<555555<<<<<<<', open: '002554323345448855325748998532', vis: '---eeeee---------oooooooo-----', emotion: 'urgent'),
      CommsLine(id: 'groundMissileLaunch.h5', speaker: 'sparrow', duration: 2.1, text: 'Something\'s coming up at you!', mouth: '00044<<<<<4444444455500000<<<<22', open: '00167898557787756874211127899742', vis: '-------ee---------ooee----------', emotion: 'panicked'),
