    ttl: 3.0,
    group: 'ground',
    lines: [
      CommsLine(id: 'groundPressureEased.h0', speaker: 'march', duration: 1.999, text: 'We\'re pushing them back! Keep it up!', mouth: '555555======<<<<==0000444<<<<<', open: '067445657786899853211577789853', vis: 'oooo--eeeeoooeeeeee-----------', emotion: 'triumphant'),
      CommsLine(id: 'groundPressureEased.h1', speaker: 'kessler', duration: 2.1, text: 'They\'re running! Bulwark advances!', mouth: '33355<<<<22000000<<<<<<<<<<<==00', open: '05777988743211687885668886654211', vis: '---oo-----------------------ee--', emotion: 'excited'),
      CommsLine(id: 'groundPressureEased.h2', speaker: 'voss', duration: 2.577, text: 'Line\'s holding. We\'ve got room to breathe.', mouth: '22<<<<<<555=====000000<<<<<<444<<<<2200', open: '048998667777765321168688689877688874211', vis: '--------oooeee-------------------------', emotion: 'warm'),
      CommsLine(id: 'groundPressureEased.h3', speaker: 'mensah', duration: 2.331, text: 'Granite\'s moving forward again. Thanks to you.', mouth: '222<<<<<4444<<<<3322200000===<<<<22', open: '02688578774689974443211278657899743', vis: '-----------ooo------------ee-------', emotion: 'warm'),
      CommsLine(id: 'groundPressureEased.h4', speaker: 'admiral', duration: 3.154, text: 'The ground line is holding. Well done, everyone.', mouth: '3333<<<<<<<<<55<<=====4433==0000<<<<<<<<44444422', open: '054689988999856887437877654321168989999877777642', vis: '-----------ooooooee-------eeeeoo----------------', emotion: 'warm'),
    ],
  ),
  'transmissionMission': CommsTriggerSpec(
    name: 'transmissionMission',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.h0', speaker: 'admiral', duration: 5.573, text: 'Pilot, Overwatch. The fleet is moving on your signal. What you do next decides this war.', mouth: '===<<<<=======4444===00000333<<<<<<<<<<<<<<====44440000000<<<<<<======44444433444422', open: '026887553258787774553211006568878899898889876777643211058788899875456477745654776532', vis: 'ee-----ee---------eee-----------oooo-------eeee----------------eeeeeee--------------', emotion: 'calm'),
      CommsLine(id: 'transmissionMission.h1', speaker: 'lindqvist', duration: 4.692, text: 'Beacon here. Long-range scans show the brood massing ahead. Stay sharp.', mouth: '33333333222000000000<<<<<<==<<<<===555<<5555333===3330000===<<444442200', open: '06766645442110000017889998778888778776887478546766643211023688777753211', vis: '-------------------------eee--ooeeeooooooo-----ee---ee---ee------------', emotion: 'calm'),
      CommsLine(id: 'transmissionMission.h2', speaker: 'admiral', duration: 3.745, text: 'Every sector you clear brings our people home. Thank you, pilot.', mouth: '===============44444<<<<<<<<<<<<<<555500000<<33334444====', open: '068677587687853777768886886768789876421100688665677876321', vis: 'ee------eeeoo--------oo-----------oooo---------------ee--', emotion: 'warm'),
    ],
  ),
  'transmissionMission.1': CommsTriggerSpec(
    name: 'transmissionMission.1',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.1.h0', speaker: 'admiral', duration: 4.017, text: 'Krybor\'s frontier is waiting. The outpost families are counting on you, pilot.', mouth: '00000<<==<<==44444333==0000000<<<<<<<<<<<44===<<<<<<33444==00', open: '0168788768867776776665321100678858866899977557888886566664321', vis: '-------eeeeee--------eee-------------------eeeoooooo-----ee--', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.1.h1', speaker: 'kestrel', duration: 5.24, text: 'Krybor ridge ahead. Brood scouts everywhere. Keep your eyes moving.', mouth: '000<<<<<<<<<<<<<44444==0000<<<<====<<<==444444433==00000044==<<<<<<<<<<<4445555', open: '0048998999889878777653211358999654788653667777765321100016746885788878987765532', vis: '---------------------ee-----oooeee----ee---------ee--------ee--------ooo---oo--', emotion: 'calm'),
    ],
  ),
  'transmissionMission.2': CommsTriggerSpec(
    name: 'transmissionMission.2',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.2.h0', speaker: 'admiral', duration: 4.906, text: 'Next stop, the Ringfall belt. Break their supply line and the brood starves.', mouth: '55<<====4444000<<<<<<<444422000000000000444<<<<<<<<<<<333<<<<=====444===00', open: '05885436774321688995687776332110001786787768999998589864788865547876444321', vis: 'ooooeee--------------------------------------------------ooooeee-----eee--', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.2.h1', speaker: 'lindqvist', duration: 4.22, text: 'Ringfall patrols are dense. Fly fast, don\'t linger in the rings.', mouth: '33<<44555553333334444==00000000<<<<<<<===000<<<<<<334444455===00', open: '0689777543356554577643321100017886888643211689788766776766643211', vis: '------oooo-----------eee--------------eee----------------ooeee--', emotion: 'calm'),
    ],
  ),
  'transmissionMission.3': CommsTriggerSpec(
    name: 'transmissionMission.3',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.3.h0', speaker: 'admiral', duration: 4.519, text: 'Ember Moon. Their foundries build every demon you\'ve fought. Shut them down.', mouth: '==<<<<<<<<<33300000033<<<<<<<<<<<<<4444<<<<<<555<<<=========<<<<<222', open: '05888999887653211068558998876788678778689988874788643357678788875421', vis: 'eeee--oo------------------------------oo--ooooo----eeee-------------', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.3.h1', speaker: 'nomad', duration: 3.926, text: 'It gets hot over the Ember forges. Trust your instruments.', mouth: '334444=======<<<<<<<<<<<<<<<44===000000000===<<<<==<<<<==00', open: '06778543277678989999998799987763211000036876489997688753321', vis: '------eeee---------oo--ooooo--ee----------eee----ee----ee--', emotion: 'calm'),
    ],
  ),
  'transmissionMission.4': CommsTriggerSpec(
    name: 'transmissionMission.4',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.4.h0', speaker: 'admiral', duration: 3.576, text: 'The Hollow answers one command. Find it, and cut it.', mouth: '444<<<<<<<44444<<<55533222000000<<<<===000<<========00', open: '067899988877767888676654321100068987532115887546633211', vis: '----------------oooo----------------eee-----eee---ee--', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.4.h1', speaker: 'wisp', duration: 3.716, text: 'The Hollow\'s towers are broadcasting something. I\'ll keep listening.', mouth: '3344<<<<===<<<===3333334433333322333300000<<==333==33333', open: '05778998657888764647866765565663465421110588665664455432', vis: '-------eeeeeeeee----oo--------------ee------ee---ee-----', emotion: 'calm'),
    ],
  ),
  'transmissionMission.5': CommsTriggerSpec(
    name: 'transmissionMission.5',
    priority: 6,
    cooldown: 30.0,
    ttl: 8.0,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionMission.5.h0', speaker: 'admiral', duration: 5.08, text: 'The Carrier. This is the heart of the brood. Everything we have is behind you.', mouth: '555==444433220000000<<<<<<<<<<<<<<<<<<<<44==0000000<<<<<<<<<<4433333444333222', open: '04755777765421100037885585764887666867887742111068788999988886756656776665321', vis: 'oooee------------------ooo---------oo-----eee---------oooo-------------------', emotion: 'warm'),
      CommsLine(id: 'transmissionMission.5.h1', speaker: 'lindqvist', duration: 4.672, text: 'All fleet guns are at your disposal. Break the field, then the hatch.', mouth: '000000<<554444<<44444444===<<<3322000000000<<<<<4444422000<<<4444====00', open: '00000689747746887778577664789665321100000058867477766421168987763465321', vis: '-----ooooo--------------eeeooo-----------------------------------eeee--', emotion: 'calm'),
    ],
  ),
  'transmissionJunior': CommsTriggerSpec(
    name: 'transmissionJunior',
    priority: 3,
    cooldown: 120.0,
    ttl: 6.0,
    chance: 0.35,
    transmission: true,
    lines: [
      CommsLine(id: 'transmissionJunior.h0', speaker: 'pip', duration: 3.09, text: 'Captain? I just wanted to say I\'ve learned so much from you!', mouth: '33333333334444<<<<<<<<<<44<<<===<<<<<<<<<<<5555', open: '06857874327787897868885377888767888986788876321', vis: '--------------------ee-------eeeeoo--------oo--', signature: true, emotion: 'excited'),
      CommsLine(id: 'transmissionJunior.h1', speaker: 'pip', duration: 3.193, text: 'Do you think I\'ll get my own ship someday? A real one?', mouth: '==<<<<33<<<<<<<<<<<<<<===33<<<<<<2222255<<<<<<<<', open: '058898658868878788688876866888887421687689999853', vis: 'eeeee----eeee-------ooee------------oooo--oooo--', emotion: 'excited'),
      CommsLine(id: 'transmissionJunior.h2', speaker: 'sunny', duration: 3.719, text: 'Quick question. Can demons get sunburns? Asking for science.', mouth: '3332244======0000555<<<<<<<<<<<<<<<<====<<<<<<<==<<<<222', open: '06642775355321116757899987854688898753258857878758887432', vis: '-------eeeeee----oo---------------ooeeee----oooee-------', signature: true, emotion: 'teasing'),
      CommsLine(id: 'transmissionJunior.h3', speaker: 'rook', duration: 3.186, text: 'Betting pool says you\'ll beat my score. I put money on you!', mouth: '222332255==333333333=====<<<<<<<<<<<<<<<<<<<<222', open: '034553244336656536556654488867868789889999986432', vis: '-------ooee---------eeeeeoo---------------------', emotion: 'teasing'),
      CommsLine(id: 'transmissionJunior.h4', speaker: 'sparrow', duration: 3.314, text: 'When this is over, first round\'s on me. Deal?', mouth: '555<<<<55<<<<<<==0000===<<<44455555000000000<<<<22', open: '02789987789888632115876788876666543211000447888532', vis: 'ooooooooo------ee----ee-------ooooee--------------', emotion: 'warm'),
      CommsLine(id: 'transmissionJunior.h5', speaker: 'wisp', duration: 3.644, text: 'I logged your last run. Your dodge rate is ridiculous.', mouth: '33<<<44<<<<<==44555500000000000<<<<<<3333333=========00', open: '0589976889987577653211000000566897788655455763455333211', vis: '------------ee--oooo-----------ooo----------eeeeeeeee--', emotion: 'calm'),
      CommsLine(id: 'transmissionJunior.h6', speaker: 'nomad', duration: 3.058, text: 'Thirty years flying, and you still surprise me.', mouth: '000<<==<<<<<<<<<<<<<2200000<<<==<<5555<<<<<222', open: '0058866899998568886532110068986788664789866432', vis: '-----ee-----eeoo-------------eeeooooo---------', emotion: 'warm'),
      CommsLine(id: 'transmissionJunior.h7', speaker: 'kestrel', duration: 2.849, text: 'Between us? You fly like a natural.', mouth: '555533<<<<<==000000033<<<<<<<<<<55444220000', open: '0377568998743211047856899988999865675321100', vis: 'oo---------eee--------------oooooo---------', emotion: 'warm'),
      CommsLine(id: 'transmissionJunior.h8', speaker: 'pip', duration: 2.93, text: 'I named my training drone after you! Is that weird?', mouth: '==<<<<<<44<<<<<<<<<44<<<<<<<2222<<<<<<<<<555', open: '06899999768888899997788888874216899679888753', vis: 'ee------------------------oo-------ooee--ooo', emotion: 'excited'),
      CommsLine(id: 'transmissionJunior.h9', speaker: 'anvil', duration: 3.228, text: 'Hydrate, pilot. Commander\'s orders. Well, my orders.', mouth: '22222222233220000<<<<<<<<<==0000<<<5555<<<<<<==00', open: '0368666435542111589998986442110689854578998642211', vis: '----------------------oo--ee-----oooo----oo--ee--', emotion: 'teasing'),
      CommsLine(id: 'transmissionJunior.h10', speaker: 'sunny', duration: 2.019, text: 'Fun fact: you\'re the brightest star in this sector.', mouth: '33<<<<===55<<<<<<<<<<<<<<<33300', open: '0688985323788788867888868555321', vis: '------eeoooo---------ooooo-----', signature: true, emotion: 'teasing'),
      CommsLine(id: 'transmissionJunior.h11', speaker: 'rook', duration: 2.994, text: 'Admiral says I talk too much. Rook, out. Wait, one more thing.', mouth: '223333333333333355555555==<<<=====55<<<<<3333', open: '035665555534874555432687468974326877899566432', vis: '----------------oooooo--eee--eeeeeoooo-------', emotion: 'teasing'),
    ],
  ),
  'terrainAhead': CommsTriggerSpec(
    name: 'terrainAhead',
    priority: 3,
    cooldown: 20.0,
    ttl: 3.0,
    group: 'ground',
