      CommsLine(id: 'skirmishWon.h5', speaker: 'voss', duration: 1.839, text: 'Ha! They did not see that coming!', mouth: '2244====<<<<<<<<<<<<<<<<<<<<', open: '0476421588999547887468886432', vis: '----eeeoooo-----------------', emotion: 'triumphant'),
